+    private func applyQAFixture() {
+        #if DEBUG
+        guard !appliedQAFixture else { return }
+        appliedQAFixture = true
+        let args = ProcessInfo.processInfo.arguments
+        guard let index = args.firstIndex(of: "-studio-tool"), args.indices.contains(index + 1) else { return }
+        switch args[index + 1] {
+        case "lettering":
+            canvas.checkpoint(); beneath = canvas.px; writing = true; typing = false
+            words = "MAKE\nLIGHT"; wordScale = 2
+            wordColors = Array(repeating: "#E8B04B", count: 4) + Array(repeating: "#F7EDDC", count: 5)
+            canvas.stamp(text: words, over: beneath, rgb: ink, size: 2, colors: wordInks)
+        case "framing": framing = FramingJob(source: [MediaQA.source()])
+        case "made-sample":
+            let side = canvas.side, blank = canvas.px
+            let first = QALetteringLayout(text: "MAKE\nLIGHT", side: side, size: 2)
+                .render(over: blank, rgb: (247, 237, 220), colors: Array(repeating: (232, 176, 75), count: 4))
+            let second = QALetteringLayout(text: "STAY\nLATE", side: side, size: 2)
+                .render(over: blank, rgb: (119, 164, 156))
+            if kept.made.isEmpty {
+                kept.keep(first); kept.keep(second)
+                var px = blank
+                for y in 0..<side { for x in 0..<side {
+                    let offset = (y * side + x) * 3
+                    let light = 0.5 + 0.5 * sin(Double(x + y) / Double(side) * .pi * 3)
+                    px[offset] = UInt8(35 + light * 130); px[offset + 1] = UInt8(42 + light * 48); px[offset + 2] = UInt8(70 + light * 42)
+                } }
+                kept.keep(px)
+            }
+        default: break
+        }
+        #endif
+    }
